package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Move the loaded claim to another person on the sheet. Only a role the sheet's permission matrix lets reassign
 *  may (by default a steward), and only a DRAFT, OPEN or PENDING
 *  claim that is not a correction (a correction names a claim of its own person), to another person it may be
 *  dated for (not retired before its date). It keeps its number and date, and loses any figure a statement bound
 *  it to: its due is live again until its new person's next statement. A move another user's change got to first
 *  is refused. */
public class SaveReassign {
    public void save(@Val ReassignInput input, @Val Claim loaded, ClaimRepository repository,
            PersonRepository people, RoleRepository roles, SettingRepository settings, Out<ClaimResponse> saved)
            throws ClaimStatusNotAllowedException, PersonNotFoundException, RetiredPersonException {
        saved.set(ClaimReassign.move(input, loaded, repository, people, roles, settings, false));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Move each selected claim to the chosen person, in list order (people in the order they were added, newest claim
 *  first within a person, as the sheet was when the move began), by exactly the rules of moving one claim: each
 *  that goes through gets its CLAIM_REASSIGNED line and then how the sheet's figures moved over it. A selected claim
 *  that cannot be moved (the sheet is archived, not on the sheet, not allowed by the user's role or from its status,
 *  a correction, to an unknown person or one retired before its date, or dated in a closed period) is left as it is
 *  and counted as refused. */
public class BulkReassignClaims {
    public void reassign(@PathVariable("sheetId") String sheetId, @Val BulkReassignInput input, ClaimRepository claims,
            PersonRepository people, PeriodRepository periods, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, Rollups rollups, Audit audit, Out<BulkReassignResponse> result) {
        String sheet = sheetId.trim();
        periods.lockSheet(sheet);
        int reassigned = 0;
        if (sheets.archived(sheet)) {
            result.set(new BulkReassignResponse(0, input.claimIds().size()));
            return;
        }
        List<Claim> selected = new ArrayList<>();
        for (Person person : people.list(sheet)) {
            claims.listForPerson(sheet, person.id()).stream()
                    .filter(c -> input.claimIds().contains(c.id())).forEach(selected::add);
        }
        ReassignInput move = new ReassignInput(input.user(), input.personId());
        for (Claim listed : selected) {
            Claim claim = claims.find(sheet, listed.id());
            if (claim == null || periods.closedOn(sheet, claim.dueBy()) != null) {
                continue;
            }
            Rollup before = rollups.take(sheet);
            ClaimResponse saved;
            try {
                saved = ClaimReassign.move(move, claim, claims, people, roles, settings, true);
            } catch (ClaimStatusNotAllowedException | PersonNotFoundException | RetiredPersonException refused) {
                continue;
            }
            ClaimReassign.audit(move, claim, saved, people, audit);
            rollups.record(sheet, input.user(), before);
            reassigned++;
        }
        result.set(new BulkReassignResponse(reassigned, input.claimIds().size() - reassigned));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Record the stored move in the audit file, naming the claim like every claim line (with its new person), then
 *  the person it moved from and to. */
public class AuditClaimReassigned {
    public void audit(@Val ReassignInput input, @Val Claim loaded, @Val ClaimResponse saved,
            PersonRepository people, Audit audit) {
        ClaimReassign.audit(input, loaded, saved, people, audit);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;

/** Moving one claim to another person, shared by a single move and a bulk one (see {@link SaveReassign}). */
final class ClaimReassign {
    private ClaimReassign() {
    }

    /** Move the claim by the rules of {@link SaveReassign}, answering it as moved. A bulk move ({@code bulk}) also lets a claim
     *  "move" to the person it already belongs to: it is written (losing any statement figure) and audited as a
     *  move like any other. */
    public static ClaimResponse move(ReassignInput input, Claim loaded, ClaimRepository repository,
            PersonRepository people, RoleRepository roles, SettingRepository settings, boolean bulk)
            throws ClaimStatusNotAllowedException, PersonNotFoundException, RetiredPersonException {
        if (!settings.permissions(loaded.sheetId()).allows("reassign", roles.of(loaded.sheetId(), input.user()))) {
            throw new ClaimStatusNotAllowedException("Your role may not move a claim to another person on this sheet.");
        }
        if (!loaded.status().unsettled() && loaded.status() != ClaimStatus.DRAFT) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot move; only a DRAFT, OPEN or PENDING one can.");
        }
        if (loaded.corrects() != null) {
            throw new ClaimStatusNotAllowedException("A correction cannot move to another person.");
        }
        Person to = people.find(loaded.sheetId(), input.personId());
        if (to == null) {
            throw new PersonNotFoundException(String.valueOf(input.personId()));
        }
        if (!bulk && to.id() == loaded.personId()) {
            throw new ClaimStatusNotAllowedException("The claim is already " + to.name() + "'s.");
        }
        RetiredPersonException.refuse(to, loaded.date());
        if (!repository.reassign(loaded, to.id())) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        return ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), to.id(), loaded.amount(),
                loaded.date(), loaded.note(), loaded.status(), loaded.number(), loaded.settledDue(),
                loaded.openedBy(), false, null, loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(),
                loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded(), loaded.ref(), loaded.tags()));
    }

    /** The CLAIM_REASSIGNED line: the claim like every claim line (with its new person), then the person it moved
     *  from and to. */
    public static void audit(ReassignInput input, Claim loaded, ClaimResponse saved, PersonRepository people,
            Audit audit) {
        var from = people.find(loaded.sheetId(), loaded.personId());
        var to = people.find(loaded.sheetId(), saved.personId());
        audit.record("CLAIM_REASSIGNED sheet=" + loaded.sheetId() + " by=" + input.user()
                + " person=" + to.name() + " amount=" + saved.amount() + " date=" + saved.date()
                + (saved.number() != null ? " number=" + saved.number() : "")
                + " from=" + from.name() + " to=" + to.name());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user and a person to move the claim to. */
public class ValidateReassign {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        long personId;
        try {
            personId = Long.parseLong(request.personId() == null ? "" : request.personId().trim());
        } catch (NumberFormatException e) {
            throw new InvalidClaimException("Choose the person to move the claim to.");
        }
        body.set(new ReassignInput(request.user().trim(), personId));
    }
}

